.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ── Form field wrapper ──────────────────────────────────────── */
.form-field {
  margin-bottom: 1.75rem;
}

/* ── Fieldset / Legend ───────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
  line-height: 1.4;
  padding: 0;
}

/* ── Radio options list ──────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

/* ── Individual option row ───────────────────────────────────── */
.radio-option {
  position: relative;
}

/* Native input: invisible but positioned over the custom dot
   so pointer/touch events land on it. */
.radio-option input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  top: 50%;
  left: 1rem;
  transform: translateY(-50%);
  margin: 0;
  cursor: pointer;
  z-index: 1;
}

/* Styled label acts as the visible control */
.radio-option label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  background: var(--bg-option);
  border: 1.5px solid var(--border);
  border-radius: 0.625rem;
  cursor: pointer;
  width: 100%;
  font-size: 0.9375rem;
  color: var(--text-primary);
  transition: background 0.15s ease, border-color 0.15s ease;
  user-select: none;
}

/* Custom radio circle */
.radio-option label::before {
  content: "";
  display: inline-flex;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  border: 2px solid var(--text-muted);
  transition: border-color 0.15s ease, background-color 0.15s ease,
    box-shadow 0.15s ease;
}

/* Hover */
.radio-option:hover label {
  background: var(--bg-option-hover);
  border-color: var(--border-hover);
}
.radio-option:hover label::before {
  border-color: var(--accent);
}

/* Checked */
.radio-option input[type="radio"]:checked + label {
  background: var(--bg-option-selected);
  border-color: var(--accent);
}
.radio-option input[type="radio"]:checked + label::before {
  background-color: var(--accent);
  border-color: var(--accent);
  box-shadow: inset 0 0 0 3px var(--bg-option-selected);
}

/* Focus-visible — outline on the label */
.radio-option input[type="radio"]:focus-visible + label {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

/* Error state */
.radio-option input[type="radio"][aria-invalid="true"] + label {
  border-color: var(--error);
}

/* ── Error message ───────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  color: var(--error);
  font-size: 0.875rem;
  margin-top: 0.75rem;
}
.error-message::before {
  content: "⚠";
  flex-shrink: 0;
  font-size: 0.875rem;
  line-height: 1;
}

/* ── Status / success message ────────────────────────────────── */
.status-message {
  min-height: 1.5rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--success);
  margin-bottom: 1.25rem;
}

/* ── Submit button ───────────────────────────────────────────── */
button[type="submit"] {
  display: block;
  width: 100%;
  padding: 0.875rem 1.5rem;
  background: var(--accent);
  color: var(--accent-text);
  border: none;
  border-radius: 0.625rem;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}
button[type="submit"]:hover {
  background: var(--accent-hover);
}
button[type="submit"]:active {
  transform: scale(0.99);
}
button[type="submit"]:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
