fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
  line-height: 1.4;
  padding: 0;
}

