(function () {
  'use strict';

  const form = document.getElementById('preferences-form');
  const radios = Array.from(form.querySelectorAll('input[name="notification"]'));
  const errorEl = document.getElementById('notification-error');
  const statusEl = document.getElementById('form-status');

  const LABELS = { email: 'Email', sms: 'SMS', push: 'Push Notifications' };

  function clearError() {
    errorEl.hidden = true;
    errorEl.textContent = '';
    radios.forEach((r) => r.removeAttribute('aria-invalid'));
  }

  function showError(msg) {
    errorEl.textContent = msg;
    errorEl.hidden = false;
    radios.forEach((r) => r.setAttribute('aria-invalid', 'true'));
    // Move focus to the first radio so AT reads the group description
    radios[0].focus();
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    statusEl.textContent = '';

    const selected = radios.find((r) => r.checked);

    if (!selected) {
      showError('Error: Please select a notification preference.');
      return;
    }

    clearError();
    statusEl.textContent = `Preference saved: ${LABELS[selected.value]}.`;
  });

  // Clear error as soon as the user picks an option
  radios.forEach((radio) => {
    radio.addEventListener('change', () => {
      clearError();
      statusEl.textContent = '';
    });
  });
})();

