:root {
  --bg-page: #0d0d14;
  --bg-card: #16161f;
  --bg-option: #1d1d28;
  --bg-option-hover: #252535;
  --bg-option-selected: #1e1a3a;
  --border: #2a2a3c;
  --border-hover: #5b50d6;
  --accent: #7b6ef6;
  --accent-hover: #6b5ee6;
  --accent-text: #ffffff;
  /* Button needs a darker base so white text clears 4.5 : 1 (#5048d4 ≈ 5.9 : 1) */
  --btn-bg: #5048d4;
  --btn-bg-hover: #5c52dc;
  --text-primary: #e2e2f0;
  --text-secondary: #9090aa;
  --text-muted: #55556a;
  --error: #f87171;
  --success: #4ade80;
  --focus-ring: 0 0 0 3px rgba(123, 110, 246, 0.55);
}

/* ── Reset ───────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── Base ────────────────────────────────────────────────────── */
body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: var(--accent-text);
  padding: 0.5rem 1.25rem;
  border-radius: 0 0 0.5rem 0.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  text-decoration: none;
  z-index: 9999;
  transition: top 0.1s ease;
}
.skip-link:focus {
  top: 0;
}

/* ── Card ────────────────────────────────────────────────────── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 1rem;
  padding: 2.5rem 2.25rem;
  width: 100%;
  max-width: 540px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

/* ── Heading ─────────────────────────────────────────────────── */
h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 1.5rem;
}

/* ── Required note ───────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ── Screen-reader-only utility ──────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ── Form field wrapper ──────────────────────────────────────── */
.form-field {
  margin-bottom: 1.75rem;
}

/* ── Fieldset / Legend ───────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
  line-height: 1.4;
  padding: 0;
}

/* ── Radio options list ──────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

/* ── Individual option row ───────────────────────────────────── */
.radio-option {
  position: relative;
}

/* Native input: invisible but positioned over the custom dot
   so pointer/touch events land on it. */
.radio-option input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  top: 50%;
  left: 1rem;
  transform: translateY(-50%);
  margin: 0;
  cursor: pointer;
  z-index: 1;
}

/* Styled label acts as the visible control */
.radio-option label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
